package com.codenzic.workspace.department.infrastructure; import com.codenzic.workspace.department.domain.Department; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface DepartmentRepository extends JpaRepository<Department,UUID>{List<Department> findAllByOrganizationId(UUID organizationId); boolean existsByIdAndOrganizationId(UUID id, UUID organizationId); Optional<Department> findByIdAndOrganizationId(UUID id,UUID organizationId);}